<?php
require 'config.php';require 'includes/functions.php';require_login();$u=current_user($pdo);$s=$pdo->prepare('SELECT * FROM orders WHERE user_id=? ORDER BY created_at DESC');$s->execute([$u['id']]);$orders=$s->fetchAll();$pageTitle='My Orders';require 'includes/header.php';?>
<div class="section-head"><div><div class="eyebrow">Order history</div><h1>My orders</h1></div><a class="btn" href="index.php">Continue shopping</a></div>
<?php if(!$orders):?><div class="panel"><h3>No orders yet</h3><p class="muted">Your orders will appear here after checkout.</p><a class="btn" href="cart.php">View basket</a></div><?php else:?><div class="panel table-wrap"><table><thead><tr><th>Order</th><th>Date</th><th>Total</th><th>Payment</th><th>Fulfilment</th><th>Items</th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td>#<?=$o['id']?></td><td><?=e($o['created_at'])?></td><td><?=money($o['total'])?></td><td><span class="status <?=e($o['payment_status'])?>"><?=e($o['payment_status'])?></span><?php if($o['payment_status']!=='Paid'):?><br><span class="small muted">If you cancelled checkout, contact the shop for a new payment link.</span><?php else:?><br><span class="small muted">Confirmed <?=e($o['paid_at']??'')?></span><?php endif;?></td><td><span class="status <?=e($o['status'])?>"><?=e($o['status'])?></span></td><td><?php $i=$pdo->prepare('SELECT product_name,quantity FROM order_items WHERE order_id=?');$i->execute([$o['id']]);foreach($i->fetchAll() as $it)echo e($it['product_name']).' × '.(int)$it['quantity'].'<br>';?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?><?php require 'includes/footer.php';?>